<?php $wp=wf_project($r['id']);if($wp&&in_array($r['status'],['Blocked','Needs Clarification'],true)): $block=one('SELECT * FROM workflow_submissions WHERE id=? AND research_id=?',[$wp['blocker_id'],$r['id']]); ?>
<section class="form-panel resolution-panel" id="workflow-response"><h2>Respond to <?=e(strtolower($r['status']))?></h2><?php if($block): ?><p><strong><?=e($block['reason'])?></strong></p><?=prose($block['body'])?><p><strong>Needed:</strong> <?=e($block['next_action'])?></p><?php endif ?><p>Your response becomes part of the public research context. It returns the project to planning for reassessment; earlier work stays in the ledger.</p>
<form method="post"><?=csrf()?><input type="hidden" name="action" value="workflow-resolve"><input type="hidden" name="round_no" value="<?=e($wp['round_no'])?>"><?php field('Response or corrected scope','response','','textarea',true);field('Short reason for this update','reason','','text',true); ?><button>Respond and resume planning</button></form></section>
<?php endif ?>
